solution.js:
function kthSmallest(root, k) {
  const stack = []
  let node = root
  while (node || stack.length) {
    while (node) {
      stack.push(node)
      node = node.left
    }
    node = stack.pop()
    k--
    if (k === 0) return node.val
    node = node.right
  }
  return null
}

